// Compile tokens.source.mjs into tokens.css and tokens.json, and audit the result.
//
//   node docs/design/tokens/build-tokens.mjs           write both files, then audit
//   node docs/design/tokens/build-tokens.mjs --check   audit only; also fail when the
//                                                      generated files are out of date
//
// No dependencies. Requires Node.js 20 or later.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { contrast, deltaE, hexToOklch, hexToRgb, over } from './color-math.mjs';
import {
  breakpoints,
  motion,
  primitives,
  radius,
  semantic,
  shadow,
  sizing,
  spacing,
  typography,
  viz,
  zIndex,
} from './tokens.source.mjs';

const here = path.dirname(fileURLToPath(import.meta.url));
const THEMES = ['light', 'dark'];

// --- Resolution ------------------------------------------------------------
const primitiveMap = new Map();
for (const [rampName, steps] of Object.entries(primitives)) {
  for (const [step, hex] of Object.entries(steps)) primitiveMap.set(`${rampName}-${step}`, hex);
}

const isReference = (value) => primitiveMap.has(value);

function resolve(value) {
  if (isReference(value)) return primitiveMap.get(value);
  return value;
}

const roles = { ...semantic, ...viz.roles };
const resolved = { light: new Map(), dark: new Map() };
for (const theme of THEMES) {
  for (const [name, hex] of primitiveMap) resolved[theme].set(name, hex);
  for (const [name, entry] of Object.entries(roles)) resolved[theme].set(name, resolve(entry[theme]));
  for (const slot of viz.categorical) resolved[theme].set(slot.name, slot[theme]);
}

// --- CSS -------------------------------------------------------------------
function cssValue(value) {
  return isReference(value) ? `var(--${value})` : value;
}

function buildCss() {
  const out = [];
  out.push('/* Connect design tokens. Generated by build-tokens.mjs from tokens.source.mjs; do not edit. */');
  out.push('');
  out.push(':root,');
  out.push('[data-theme="light"] {');
  out.push('  color-scheme: light;');
  out.push('');
  out.push('  /* Primitive ramps */');
  for (const [name, hex] of primitiveMap) out.push(`  --${name}: ${hex};`);
  out.push('');
  out.push('  /* Semantic roles: light theme */');
  for (const [name, entry] of Object.entries(roles)) out.push(`  --${name}: ${cssValue(entry.light)};`);
  out.push('');
  out.push('  /* Chart palette: light theme (fixed order) */');
  for (const slot of viz.categorical) out.push(`  --${slot.name}: ${slot.light};`);
  out.push('');
  out.push('  /* Shadows: light theme */');
  for (const [name, value] of shadow) out.push(`  --${name}: ${value.light};`);
  out.push('');
  out.push('  /* Typography */');
  out.push(`  --font-sans: ${typography.families.sans};`);
  out.push(`  --font-mono: ${typography.families.mono};`);
  out.push('  --script-size-bump: 0px;');
  out.push('  --script-leading-bump: 0px;');
  for (const style of typography.styles) {
    out.push(`  --${style.name}-size: ${style.size}px;`);
    out.push(`  --${style.name}-line: ${style.line}px;`);
    out.push(`  --${style.name}-weight: ${style.weight};`);
  }
  out.push('');
  out.push('  /* Spacing, radius, sizing */');
  for (const [name, px] of spacing) out.push(`  --${name}: ${px}px;`);
  for (const [name, px] of radius) out.push(`  --${name}: ${px}px;`);
  for (const [name, px] of sizing) out.push(`  --${name}: ${px}px;`);
  out.push('');
  out.push('  /* Motion and stacking */');
  for (const [name, value] of motion) out.push(`  --${name}: ${value};`);
  for (const [name, value] of zIndex) out.push(`  --${name}: ${value};`);
  out.push('}');
  out.push('');

  const darkBlock = (indent) => {
    const lines = [`${indent}color-scheme: dark;`];
    for (const [name, entry] of Object.entries(roles)) lines.push(`${indent}--${name}: ${cssValue(entry.dark)};`);
    for (const slot of viz.categorical) lines.push(`${indent}--${slot.name}: ${slot.dark};`);
    for (const [name, value] of shadow) lines.push(`${indent}--${name}: ${value.dark};`);
    return lines;
  };
  out.push('/* Dark theme: follows the system setting unless a theme is chosen explicitly. */');
  out.push('@media (prefers-color-scheme: dark) {');
  out.push('  :root:not([data-theme="light"]) {');
  out.push(...darkBlock('    '));
  out.push('  }');
  out.push('}');
  out.push('');
  out.push('[data-theme="dark"] {');
  out.push(...darkBlock('  '));
  out.push('}');
  out.push('');
  out.push('/* Arabic text is set one pixel larger with two pixels more leading. */');
  out.push(':lang(ar) {');
  out.push(`  --script-size-bump: ${typography.script.arabicSizeBump}px;`);
  out.push(`  --script-leading-bump: ${typography.script.arabicLeadingBump}px;`);
  out.push('}');
  out.push('');
  out.push('/* Type styles */');
  for (const style of typography.styles) {
    out.push(`.${style.name} {`);
    out.push(`  font-family: var(--font-${style.family ?? 'sans'});`);
    out.push(`  font-size: calc(var(--${style.name}-size) + var(--script-size-bump));`);
    out.push(`  line-height: calc(var(--${style.name}-line) + var(--script-leading-bump));`);
    out.push(`  font-weight: var(--${style.name}-weight);`);
    out.push('}');
  }
  out.push('');
  out.push('/* Breakpoints (reference; custom properties cannot be used in media queries):');
  for (const [name, px, usage] of breakpoints) out.push(`   ${name.padEnd(3)} ${px}px  ${usage}`);
  out.push('*/');
  out.push('');
  return out.join('\n');
}

// --- Design Tokens Community Group format (2025.10) ------------------------
function dtcgColor(value) {
  if (/^#[0-9a-f]{6}$/i.test(value)) {
    const [r, g, b] = hexToRgb(value).map((v) => Number(v.toFixed(4)));
    return { colorSpace: 'srgb', components: [r, g, b], hex: value };
  }
  const m = value.match(/^rgba\((\d+), (\d+), (\d+), ([\d.]+)\)$/);
  if (m) {
    const [r, g, b] = [m[1], m[2], m[3]].map((v) => Number((Number(v) / 255).toFixed(4)));
    return { colorSpace: 'srgb', components: [r, g, b], alpha: Number(m[4]) };
  }
  throw new Error(`Unsupported color literal: ${value}`);
}

const px = (value) => ({ value, unit: 'px' });

function buildJson() {
  const doc = {
    $description:
      'Connect design tokens (specification 018 design proposal). Generated by build-tokens.mjs from tokens.source.mjs; do not edit. Format: Design Tokens Community Group 2025.10.',
    color: { $type: 'color', primitive: {}, light: {}, dark: {} },
    font: {
      family: {
        $type: 'fontFamily',
        sans: { $value: typography.families.sans.split(',').map((s) => s.trim().replace(/^"|"$/g, '')) },
        mono: { $value: typography.families.mono.split(',').map((s) => s.trim().replace(/^"|"$/g, '')) },
      },
    },
    type: { $type: 'typography' },
    space: { $type: 'dimension' },
    radius: { $type: 'dimension' },
    size: { $type: 'dimension' },
    shadow: { light: {}, dark: {} },
    duration: { $type: 'duration' },
    easing: { $type: 'cubicBezier' },
    zIndex: { $type: 'number' },
    breakpoint: { $type: 'dimension' },
  };
  for (const [rampName, steps] of Object.entries(primitives)) {
    doc.color.primitive[rampName] = {};
    for (const [step, hex] of Object.entries(steps)) doc.color.primitive[rampName][step] = { $value: dtcgColor(hex) };
  }
  const reference = (value) => {
    const i = value.lastIndexOf('-');
    return `{color.primitive.${value.slice(0, i)}.${value.slice(i + 1)}}`;
  };
  for (const theme of THEMES) {
    for (const [name, entry] of Object.entries(roles)) {
      const value = entry[theme];
      doc.color[theme][name] = {
        $value: isReference(value) ? reference(value) : dtcgColor(value),
        $description: entry.usage,
      };
    }
    for (const slot of viz.categorical) {
      doc.color[theme][slot.name] = {
        $value: dtcgColor(slot[theme]),
        $description: `Categorical chart slot (${slot.hue}). The slot order is fixed.`,
      };
    }
    for (const [name, value, usage] of shadow) {
      doc.shadow[theme][name] = { $type: 'shadow', $value: parseShadow(value[theme]), $description: usage };
    }
  }
  for (const style of typography.styles) {
    doc.type[style.name] = {
      $value: {
        fontFamily: `{font.family.${style.family ?? 'sans'}}`,
        fontSize: px(style.size),
        fontWeight: style.weight,
        letterSpacing: px(0),
        lineHeight: Number((style.line / style.size).toFixed(4)),
      },
      $description: style.usage,
    };
  }
  for (const [name, value, usage] of spacing) doc.space[name] = { $value: px(value), $description: usage };
  for (const [name, value, usage] of radius) doc.radius[name] = { $value: px(value), $description: usage };
  for (const [name, value, usage] of sizing) doc.size[name] = { $value: px(value), $description: usage };
  for (const [name, value, usage] of motion) {
    if (name.startsWith('duration')) {
      doc.duration[name] = { $value: { value: Number.parseInt(value, 10), unit: 'ms' }, $description: usage };
    } else {
      const points = value.match(/[\d.]+/g).map(Number);
      doc.easing[name] = { $value: points, $description: usage };
    }
  }
  for (const [name, value, usage] of zIndex) doc.zIndex[name] = { $value: value, $description: usage };
  for (const [name, value, usage] of breakpoints) doc.breakpoint[name] = { $value: px(value), $description: usage };
  return `${JSON.stringify(doc, null, 2)}\n`;
}

function parseShadow(text) {
  const m = text.match(/^(-?\d+)(?:px)? (-?\d+)px (\d+)px (rgba\([^)]+\))$/);
  if (!m) throw new Error(`Unsupported shadow: ${text}`);
  return { color: dtcgColor(m[4]), offsetX: px(Number(m[1])), offsetY: px(Number(m[2])), blur: px(Number(m[3])), spread: px(0) };
}

// --- Audit -----------------------------------------------------------------
function auditContrast() {
  const failures = [];
  const rows = [];
  const need = (fg, bg, min, why) => ({ fg, bg, min, why });
  const textSurfaces = ['surface-canvas', 'surface-raised', 'surface-sunken', 'surface-overlay', 'surface-hover'];
  const checks = [];
  for (const surface of textSurfaces) {
    checks.push(need('text-primary', surface, 4.5, 'text'));
    checks.push(need('text-secondary', surface, 4.5, 'text'));
    checks.push(need('text-tertiary', surface, 4.5, 'text'));
  }
  checks.push(need('text-primary', 'surface-pressed', 4.5, 'text'));
  checks.push(need('text-primary', 'surface-selected', 4.5, 'text'));
  checks.push(need('text-secondary', 'surface-selected', 4.5, 'text'));
  checks.push(need('text-brand', 'surface-selected', 4.5, 'text'));
  checks.push(need('text-brand', 'surface-selected-hover', 4.5, 'text'));
  checks.push(need('text-brand', 'surface-canvas', 4.5, 'text'));
  checks.push(need('text-brand', 'surface-raised', 4.5, 'text'));
  checks.push(need('text-brand', 'surface-overlay', 4.5, 'text'));
  checks.push(need('text-inverse', 'surface-inverse', 4.5, 'text'));
  checks.push(need('text-on-primary', 'action-primary', 4.5, 'text'));
  checks.push(need('text-on-primary', 'action-primary-hover', 4.5, 'text'));
  checks.push(need('text-on-primary', 'action-primary-active', 4.5, 'text'));
  checks.push(need('text-on-danger', 'action-danger', 4.5, 'text'));
  checks.push(need('text-on-danger', 'action-danger-hover', 4.5, 'text'));
  for (const tone of ['success', 'warning', 'danger', 'info', 'neutral']) {
    checks.push(need(`status-${tone}-fg`, `status-${tone}-bg`, 4.5, 'text'));
    checks.push(need(`status-${tone}-fg`, 'surface-raised', 4.5, 'text'));
    checks.push(need(`status-${tone}-fg`, 'surface-canvas', 4.5, 'text'));
    checks.push(need(`status-${tone}-solid`, 'surface-raised', tone === 'warning' ? 1 : 3, 'mark'));
    checks.push(need(tone === 'warning' ? 'status-warning-on-solid' : 'status-on-solid', `status-${tone}-solid`, tone === 'neutral' ? 3 : 4.5, 'text'));
  }
  for (const surface of ['surface-canvas', 'surface-raised', 'surface-sunken']) {
    checks.push(need('border-control', surface, 3, 'control'));
    checks.push(need('border-focus', surface, 3, 'focus'));
    checks.push(need('action-primary', surface, 3, 'control'));
  }
  checks.push(need('border-focus', 'surface-selected', 3, 'focus'));
  checks.push(need('border-focus', 'surface-overlay', 3, 'focus'));

  for (const theme of THEMES) {
    for (const c of checks) {
      const ratio = contrast(resolved[theme].get(c.fg), resolved[theme].get(c.bg));
      const pass = ratio >= c.min;
      rows.push({ theme, ...c, ratio });
      if (!pass) failures.push(`${theme}: ${c.fg} on ${c.bg} is ${ratio.toFixed(2)}:1, needs ${c.min}:1 (${c.why})`);
    }
  }
  return { failures, rows };
}

// Categorical chart palette: the same gates in both themes.
const BAND = { light: [0.43, 0.77], dark: [0.48, 0.67] };
const CHROMA_FLOOR = 0.1;
const CVD_TARGET = 8;
const NORMAL_FLOOR = 15;

function auditCharts() {
  const failures = [];
  const notes = [];
  for (const theme of THEMES) {
    const palette = viz.categorical.map((slot) => slot[theme]);
    const surface = resolved[theme].get('surface-raised');
    const [lo, hi] = BAND[theme];
    for (const [i, hex] of palette.entries()) {
      const [L, C] = hexToOklch(hex);
      if (L < lo || L > hi) failures.push(`${theme}: viz-${i + 1} lightness ${L.toFixed(3)} is outside ${lo}-${hi}`);
      if (C < CHROMA_FLOOR) failures.push(`${theme}: viz-${i + 1} chroma ${C.toFixed(3)} is below ${CHROMA_FLOOR}`);
      const ratio = contrast(hex, surface);
      if (ratio < 3) notes.push(`${theme}: viz-${i + 1} is ${ratio.toFixed(2)}:1 on the chart surface; direct labels or the table view are mandatory`);
    }
    let worstCvd = Infinity;
    let worstNormal = Infinity;
    for (let i = 0; i < palette.length - 1; i += 1) {
      const cvd = Math.min(deltaE(palette[i], palette[i + 1], 'protan'), deltaE(palette[i], palette[i + 1], 'deutan'));
      const normal = deltaE(palette[i], palette[i + 1]);
      worstCvd = Math.min(worstCvd, cvd);
      worstNormal = Math.min(worstNormal, normal);
      if (cvd < CVD_TARGET) failures.push(`${theme}: viz-${i + 1} and viz-${i + 2} are ${cvd.toFixed(1)} apart under simulated deficiency, target ${CVD_TARGET}`);
      if (normal < NORMAL_FLOOR) failures.push(`${theme}: viz-${i + 1} and viz-${i + 2} are ${normal.toFixed(1)} apart, floor ${NORMAL_FLOOR}`);
    }
    // The first three slots must also separate pairwise (scatter, small multiples).
    for (let i = 0; i < 3; i += 1) {
      for (let j = i + 1; j < 3; j += 1) {
        const cvd = Math.min(deltaE(palette[i], palette[j], 'protan'), deltaE(palette[i], palette[j], 'deutan'));
        const normal = deltaE(palette[i], palette[j]);
        if (cvd < CVD_TARGET || normal < NORMAL_FLOOR) failures.push(`${theme}: viz-${i + 1} and viz-${j + 1} fail the pairwise gate (${cvd.toFixed(1)}, ${normal.toFixed(1)})`);
      }
    }
    notes.push(`${theme}: worst adjacent separation ${worstCvd.toFixed(1)} (simulated), ${worstNormal.toFixed(1)} (normal vision)`);
    // Sequential ramp: lightness must move in one direction.
    const seq = [1, 2, 3, 4, 5, 6, 7].map((n) => hexToOklch(resolved[theme].get(`viz-seq-${n}`))[0]);
    const direction = Math.sign(seq[6] - seq[0]);
    for (let i = 0; i < seq.length - 1; i += 1) {
      if (Math.sign(seq[i + 1] - seq[i]) !== direction) failures.push(`${theme}: viz-seq-${i + 1} to viz-seq-${i + 2} breaks the lightness order`);
    }
  }
  return { failures, notes };
}

// --- Main ------------------------------------------------------------------
const css = buildCss();
const json = buildJson();
const cssPath = path.join(here, 'tokens.css');
const jsonPath = path.join(here, 'tokens.json');
const checkOnly = process.argv.includes('--check');
const verbose = process.argv.includes('--verbose');
const problems = [];

if (checkOnly) {
  const same = (file, text) => fs.existsSync(file) && fs.readFileSync(file, 'utf8').replace(/\r\n/g, '\n') === text;
  if (!same(cssPath, css)) problems.push('tokens.css is out of date; run build-tokens.mjs');
  if (!same(jsonPath, json)) problems.push('tokens.json is out of date; run build-tokens.mjs');
} else {
  fs.writeFileSync(cssPath, css);
  fs.writeFileSync(jsonPath, json);
}

const contrastAudit = auditContrast();
const chartAudit = auditCharts();
problems.push(...contrastAudit.failures, ...chartAudit.failures);

if (verbose) {
  for (const row of contrastAudit.rows) {
    console.log(`${row.theme.padEnd(5)} ${row.ratio.toFixed(2).padStart(6)}  min ${String(row.min).padEnd(3)}  ${row.fg} on ${row.bg}`);
  }
}
console.log(`Contrast pairs checked: ${contrastAudit.rows.length}`);
for (const note of chartAudit.notes) console.log(`Chart palette: ${note}`);
// Scrim sanity: text behind the scrim must stop competing with the dialog.
for (const theme of THEMES) {
  const scrim = roles['surface-scrim'][theme].match(/rgba\((\d+), (\d+), (\d+), ([\d.]+)\)/);
  const tint = `#${[scrim[1], scrim[2], scrim[3]].map((v) => Number(v).toString(16).padStart(2, '0')).join('')}`;
  const dimmed = over(tint, Number(scrim[4]), resolved[theme].get('surface-canvas'));
  console.log(`Scrim over canvas (${theme}): ${dimmed}`);
}
if (problems.length > 0) {
  console.error(`\n${problems.length} problem(s):`);
  for (const p of problems) console.error(`  - ${p}`);
  process.exit(1);
}
console.log(checkOnly ? 'Tokens are up to date and pass the audit.' : 'Wrote tokens.css and tokens.json; audit passed.');
